WFI.Data.add("quest", {
  [91740] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [91743] = { "Roditori birbanti", "Recupera $N1 Stolen Books dai kobold della Northshire Valley e riportali al Brother Paxton.", "Quegli orribili kobold mi mangiano i libri! Devi riprenderli prima che divorino tutta la mia biblioteca.", "Hai già salvato i miei libri, {name}?!", "Grazie infinite! Ecco! Prendi uno di questi manuali pratici. A me non servono.\n\nMa mancano ancora tanti libri. I kobold non sembrano mangiarli. Allora perché li vogliono?", 0x5ecfe128, 0xca0dec56, 0x36c2ff3a, 0x9e3c12c9, 0xcb496646, "....." },
  [91745] = { "Consulente minerario", "Parla con Kelsey Fargo fuori dalla Echo Ridge Mine, nella Northshire Valley.", "Va' a parlare con la nuova apprendista minatrice, Kelsey Fargo. Lavora proprio fuori dalla miniera e probabilmente ha visto cosa stanno combinando i kobold. Forse, già che ci sei, può insegnarti un paio di cose sull'estrazione mineraria.", nil, "Kobold con dei libri? Sì, ho visto kobold correre avanti e indietro con dei libri, urlandosi addosso. Devono rubarli dalla biblioteca dentro l'abbazia.", 0x70de9b61, 0x928069a0, 0x595703ec, nil, 0x968f291e, "...m." },
  [91746] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [91751] = { nil, "Scuoia i lupi dell'Elwynn Forest per ottenere $N1 Rough Wolf Pelts, poi consegnale a Helene Peltskinner, vicino a Goldshire.", "Cerchi un'occasione per esercitarti a scuoiare? Di solito mio marito aiuta a cacciare i lupi, ma è impegnato su vicino all'abbazia. Mi farebbe comodo una mano a raccogliere altre pelli per finire gli ordini a cui sto lavorando.", "Fortuna con quelle pelli di lupo?", "Ottimo lavoro nel raccogliere queste pelli, {class}. Hai un vero talento per la caccia.", nil, 0x35d88064, 0x993378eb, 0xc1490377, 0x024aeaa4, "m...." },
  [91752] = { "Il quadro generale", "Recupera un sacco di libri \"illustrati\" da Shinyfinder Narf. Porta il sacco al Marshal McBride, appena dentro la Northshire Abbey.", "Ogni tanto passa un kobold urlando \"Figure per Narf!\" Non so chi sia Narf. Forse uno dei capi kobold in fondo alla miniera? Scommetto che ormai ha un sacco intero di libri.\n\nVa' a prendere quei libri e portali alla nostra forza dell'ordine locale, il Marshal McBride. Dovresti trovare un amico che ti aiuti. I kobold dentro la miniera sono molto più cattivi.", "Hai già recuperato quei libri rubati?", "Grazie per aver riportato questi libri rubati, {name}. Li riporterò subito al Brother Paxton.\n\nQui intorno stai diventando proprio <un/una> <eroe/eroina>. Ottimo lavoro!", 0xf0a9a4ae, 0x0274d4d1, 0x64d74190, 0x98bda539, 0x3c4f5b85, "....." },
  [91758] = { "Segui quel kobold!", "Parla con Tordrin Sternblade vicino alla stalla dietro la Northshire Abbey.", "Con quei kobold non hai ancora finito. Kelsey ci ha appena fatto sapere che un kobold è uscito dalla miniera con un grosso sacco di libri. Ho bisogno che tu rintracci questo kobold per recuperare i libri del Brother Paxton.\n\nVa' a parlare con Tordrin Sternblade. È il nuovo istruttore dei cacciatori appena arrivato da Ironforge. Lo trovi dietro l'abbazia, vicino alla stalla. Può aiutarti a seguire le tracce di questo ladro kobold.", nil, "Posso aiutarti a rintracciare questa canaglia. Lascia che ti prepari qualcosa.", 0x5b4c7f86, 0xba85d0f1, 0xbabf3db2, nil, 0x0f74c33b, "...m." },
  [91772] = { "Ssst! Diamo la caccia ai kobold", "Segui le tracce dei kobold e fai rapporto al Marshal Dughan, a Goldshire, con ciò che hai scoperto e il Kobold Tracking Kit.", "Bene. Prendi questo kit per seguire i kobold. Ti permetterà di seguire le tracce del kobold che preoccupa il Marshal McBride.\n\nSegui le tracce e porta ciò che trovi al Marshal Dughan, a Goldshire.\n\nHo la sensazione che queste canaglie stiano tramando qualcosa fuori da Northshire. Quindi ti servirà l'aiuto di Dughan.", "Hai capito dove sono diretti i kobold?", "Cos'è questo, {name}? Seguire le tracce dei kobold?\n\nBeh, è ovvio che sono diretti alla Fargodeep Mine! Quel posto è infestato dai kobold.\n\nBel lavoro, immagino. Mi servirà qualcuno che si occupi di quel problema.", 0xccca4f37, 0x4c6f788d, 0x88b384bf, 0x76315b25, 0x94488fef, "....." },
  [91777] = { "Libri rari", "Recupera \"Geomancy for Curious Young Wizards\" e \"Arcane Explainer: Magical Stuff in Simple Words\" e riportali al Brother Paxton, dentro la Northshire Abbey.", "Mancano solo due libri sulla lista del Brother Paxton: \"Geomancy for Curious Young Wizards\" e \"Arcane Explainer: Magical Stuff in Simple Words\".\n\nI kobold devono averli portati nella Jasperlode Mine. Ti prego, rintraccia quei due libri e riportali al Brother Paxton.\n\nMa temo che sarà piuttosto pericoloso. Se il kobold \"apprendista\" evocava un elementale, chissà cosa può fare il maestro. Se fossi in te porterei qualche amico.", "Hai già trovato tutti i miei libri scomparsi?", "Oh, {name}! Grazie infinite per aver salvato la mia biblioteca. Mi hai reso un servizio straordinario. Ti prego, prendi una di queste belle armi. Erano destinate alla milizia, ma tu puoi farne un uso migliore.", 0xa9c579cb, 0xa02ab9c4, 0xa51f628c, 0xf4232bfe, 0xb2abd943, "....." },
})
